fn build_reverse(morse: &Map[Str, Str]) -> Map[Str, Str] {
  let mut rev: Map[Str, Str] = Map[Str, Str].new();
  let mut letters: Vec[Str] = Vec[Str].new();
  letters.push("S"); letters.push("O"); letters.push("S");
  letters.push("H"); letters.push("I");
  let mut i = 0;
  while i < letters.len() {
    let ch = letters.get(i).unwrap();
    let code = morse.get(ch).unwrap();
    rev.insert(code, ch);
    i = i + 1;
  };
  rev
}

fn encode_word(word: Str, morse: &Map[Str, Str]) -> Str {
  let mut result: Str = "";
  let mut i = 0;
  while i < word.len() {
    let ch = word.get(i).unwrap();
    let code = morse.get(ch).unwrap_or("?");
    result = result + code;
    if i < word.len() - 1 { result = result + " "; };
    i = i + 1;
  };
  result
}

fn decode_morse(morse_str: Str, rev: &Map[Str, Str]) -> Str {
  let mut result: Str = "";
  let mut token: Str = "";
  let mut i = 0;
  while i < morse_str.len() {
    let ch = morse_str.get(i).unwrap();
    if ch == " " {
      let letter = rev.get(token).unwrap_or("?");
      result = result + letter;
      token = "";
    } else {
      token = token + ch;
    };
    i = i + 1;
  };
  if token != "" {
    let letter = rev.get(token).unwrap_or("?");
    result = result + letter;
  };
  result
}

fn main() -> Int {
  let morse_map = build_morse_map();
  let encoded = encode_word("SOS", &morse_map);
  io.println(encoded);

  let rev_map = build_reverse(&morse_map);
  let decoded = decode_morse("... --- ...", &rev_map);
  io.println(decoded);

  let hello_encoded = encode_word("HI", &morse_map);
  io.println(hello_encoded);
  let hello_decoded = decode_morse(".... ..", &rev_map);
  io.println(hello_decoded);

  return 0;
}
